class Solution{ListNode m(ListNode a,ListNode b){ListNode d=new ListNode(),t=d;while(a!=null&&b!=null){if(a.val<=b.val){t.next=a;a=a.next;}else{t.next=b;b=b.next;}t=t.next;}t.next=a!=null?a:b;return d.next;}public ListNode mergeKLists(ListNode[]v){if(v.length==0)return null;for(int s=1;s<v.length;s*=2)for(int i=0;i+s<v.length;i+=2*s)v[i]=m(v[i],v[i+s]);return v[0];}}
